using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

public interface IDocumentSummarizer
{
    string Summarize(string documentText, int maxSentences);
}

public partial class DocumentSummarizer : IDocumentSummarizer
{
    public string Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        var scored = ScoreSentences(sentences);

        var topSentences = scored
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index)
            .Select(s => s.Sentence);

        return string.Join(" ", topSentences);
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return SentenceSplitter()
            .Split(text.Trim())
            .Select(s => s.Trim())
            .Where(s => s.Length > 0)
            .ToList();
    }

    private static List<ScoredSentence> ScoreSentences(List<string> sentences)
    {
        // Build word frequency map (case-insensitive, ignoring short words)
        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var sentence in sentences)
        {
            foreach (var word in ExtractWords(sentence))
            {
                if (word.Length <= 2)
                    continue;

                wordFrequency.TryGetValue(word, out int count);
                wordFrequency[word] = count + 1;
            }
        }

        var scored = new List<ScoredSentence>();
        for (int i = 0; i < sentences.Count; i++)
        {
            double score = 0;
            var words = ExtractWords(sentences[i]);

            foreach (var word in words)
            {
                if (word.Length > 2 && wordFrequency.TryGetValue(word, out int freq))
                    score += freq;
            }

            // Normalize by word count to avoid biasing toward long sentences
            if (words.Length > 0)
                score /= words.Length;

            // Boost first and second sentences (they often carry key information)
            if (i == 0) score *= 1.5;
            else if (i == 1) score *= 1.25;

            scored.Add(new ScoredSentence(i, sentences[i], score));
        }

        return scored;
    }

    private static string[] ExtractWords(string sentence) =>
        WordExtractor().Matches(sentence).Select(m => m.Value).ToArray();

    [GeneratedRegex(@"(?<=[.!?])\s+")]
    private static partial Regex SentenceSplitter();

    [GeneratedRegex(@"\w+")]
    private static partial Regex WordExtractor();

    private record ScoredSentence(int Index, string Sentence, double Score);
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly IDocumentSummarizer _summarizer;

    public SummarizeController(IDocumentSummarizer summarizer)
    {
        _summarizer = summarizer;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var summary = _summarizer.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

